   warning, confidence)
select f.id, t.id, v.ratio, v.to_unit, v.amount_note, v.contexts::text[], v.scope_note, v.effect,
  v.warning, v.confidence
from (values
  ('Молоко', 'Молоко безлактозное', 1, null, '1:1', '{}', 'В любых блюдах вместо обычного молока.', 'Вкус чуть слаще.', 'Белок молока остаётся: при аллергии на молоко не подходит.', 'practice'),
