  ('Фарш свино-говяжий', 'Фарш куриный', 1, null, '1:1', '{frying,stewing,boiling,baking}', 'Котлеты, фрикадельки, тефтели.', 'Нежнее и суше, готовится быстрее.', 'Это птица.', 'practice'),
  ('Свинина', 'Говядина', 1, null, '1:1', '{stewing,frying,boiling,baking}', 'Тушение, жарка, запекание.', 'Плотнее; тушить дольше.', 'Время готовки дольше.', 'practice'),
  ('Ветчина', 'Индейка филе', 1, null, '1:1 отварной индейки', '{cold,boiling,stewing}', 'Салаты, супы.', 'Без копчёного вкуса, мягче.', 'Это птица.', 'practice'),
  ('Бекон', 'Индейка филе', 1, null, '1:1', '{frying,stewing}', 'Жарка, начинки.', 'Без копчёного вкуса, нежирно.', 'Это птица.', 'practice'),
  ('Бульон', 'Вода', 1, null, '1:1 + соль и специи по вкусу', '{boiling,stewing}', 'Супы, соусы, тушение.', 'Вкус менее насыщенный.', 'Вкус станет проще; если бульон был солёным — досолите.', 'practice'),
  ('Жир топлёный', 'Масло подсолнечное', 1, null, '1:1', '{frying,stewing}', 'Жарка и тушение.', 'Нет вкуса шкварок.', 'Вкус блюда станет проще.', 'practice'),
  ('Анчоусы', 'Оливки', 1, null, '1:1, мелко нарезать', '{cold}', 'Салаты.', 'Солоновато-пряный вкус без рыбы.', 'Оливки солёные — уменьшите соль.', 'practice'),
  ('Соус «Южный»', 'Томатная паста', 0.5, null, 'Вдвое меньше + щепотка сахара и капля уксуса', '{stewing,boiling}', 'Подливки и тушёные блюда.', 'Мягче, без пряной остроты.', 'Паста густая — разведите водой.', 'practice'),
