  ('Уксус винный', 'Уксус яблочный', 1, null, '1:1', '{cold,stewing,boiling}', 'Заправки, маринады, соусы.', 'Мягче, с яблочным оттенком.', 'Яблочный уксус тоже может содержать сульфиты — смотрите состав.', 'practice'),
  ('Уксус бальзамический', 'Уксус яблочный', 0.5, null, 'Вдвое меньше + щепотка сахара', '{cold}', 'Заправки.', 'Без сладости и густоты бальзамика.', 'Яблочный уксус тоже может содержать сульфиты — смотрите состав.', 'practice'),
  ('Горчица', 'Хрен', 1, null, '1:1', '{cold}', 'Соусы и заправки.', 'Острее, другой аромат.', 'Хрен острее — начните с половины количества.', 'practice'),
  ('Масло кунжутное', 'Масло подсолнечное', 1, null, '1:1', '{frying,cold,stewing}', 'Жарка и заправки.', 'Нет кунжутного аромата.', 'Аромат блюда изменится.', 'practice'),
  ('Сельдерей стеблевой', 'Огурец', 1, null, '1:1', '{cold}', 'Салаты.', 'Свежий хруст без аромата сельдерея.', 'Огурец даёт сок — заправляйте салат перед подачей.', 'practice'),
  ('Сельдерей корневой', 'Пастернак', 1, null, '1:1', '{boiling,stewing,baking}', 'Супы, рагу, запекание.', 'Слаще, но похож по аромату.', 'Пастернак слаще — учтите это в несладких блюдах.', 'practice')
) as v (from_name, to_name, ratio, to_unit, amount_note, contexts, scope_note, effect, warning,
